COURSE_FIGURES['w5-sqli'] =
  '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 404" role="img" aria-label="SQL injection diagram. Login input: user admin\'# and any password. Vulnerable code pastes the input into the query, giving SELECT * FROM users WHERE name = \'admin\'#\' AND pass = \'...\'; the quote closes the name and # comments out the password check, so the attacker logs in as admin. Safe code uses a parameterized query with placeholders and sends the values separately, so the login fails.">' +
  '<rect x="0" y="0" width="800" height="404" rx="12" fill="#0d0d1f"/>' +
  '<text x="24" y="34" font-family="Share Tech Mono, Consolas, monospace" font-size="13" font-weight="400" fill="#a0a0ac" text-anchor="start" letter-spacing="1.5">LOGIN FORM INPUT</text>' +
  '<rect x="24" y="46" width="360" height="40" rx="10" fill="#0d0d1f" stroke="#3a3a5c" stroke-width="1.5"/>' +
  '<text x="36" y="72" font-family="Share Tech Mono, Consolas, monospace" font-size="17" font-weight="400" fill="#e8e8e8" text-anchor="start">User:  admin\'#</text>' +
  '<rect x="416" y="46" width="360" height="40" rx="10" fill="#0d0d1f" stroke="#3a3a5c" stroke-width="1.5"/>' +
  '<text x="428" y="72" font-family="Share Tech Mono, Consolas, monospace" font-size="17" font-weight="400" fill="#e8e8e8" text-anchor="start">Pass:  anything</text>' +
  '<rect x="24" y="110" width="752" height="128" rx="10" fill="#131329" stroke="#ee2207" stroke-width="2"/>' +
  '<text x="40" y="138" font-family="Rajdhani, Segoe UI, sans-serif" font-size="19" font-weight="700" fill="#ee2207" text-anchor="start">VULNERABLE: input pasted into the query as code</text>' +
  '<text x="40" y="170" font-family="Share Tech Mono, Consolas, monospace" font-size="16" font-weight="400" fill="#e8e8e8" text-anchor="start">SELECT * FROM users WHERE name = \'admin\'#\' AND pass = \'...\'</text>' +
  '<line x1="380" y1="178" x2="394" y2="178" fill="none" stroke="#ee2207" stroke-width="3"/>' +
  '<line x1="402" y1="178" x2="560" y2="178" fill="none" stroke="#a0a0ac" stroke-width="1.5" stroke-dasharray="4 3"/>' +
  '<text x="387" y="198" font-family="Inter, Segoe UI, sans-serif" font-size="12.5" font-weight="500" fill="#ee2207" text-anchor="end">\' closes the name</text>' +
  '<text x="400" y="198" font-family="Inter, Segoe UI, sans-serif" font-size="12.5" font-weight="500" fill="#a0a0ac" text-anchor="start"># turns the rest into a comment</text>' +
  '<text x="40" y="226" font-family="Inter, Segoe UI, sans-serif" font-size="14" font-weight="500" fill="#e8e8e8" text-anchor="start">Result: logged in as admin. The password check never ran.</text>' +
  '<rect x="24" y="258" width="752" height="128" rx="10" fill="#131329" stroke="#33d17a" stroke-width="2"/>' +
  '<text x="40" y="286" font-family="Rajdhani, Segoe UI, sans-serif" font-size="19" font-weight="700" fill="#33d17a" text-anchor="start">SAFE: parameterized query keeps input as data</text>' +
  '<text x="40" y="318" font-family="Share Tech Mono, Consolas, monospace" font-size="16" font-weight="400" fill="#e8e8e8" text-anchor="start">SELECT * FROM users WHERE name = ? AND pass = ?</text>' +
  '<text x="40" y="344" font-family="Share Tech Mono, Consolas, monospace" font-size="15" font-weight="400" fill="#a0a0ac" text-anchor="start">values sent separately:  [ admin\'#  ,  anything ]</text>' +
  '<text x="40" y="374" font-family="Inter, Segoe UI, sans-serif" font-size="14" font-weight="500" fill="#e8e8e8" text-anchor="start">Result: no user is literally named admin\'#, so the login fails.</text>' +
  '</svg>';

